def forward(self, x: torch.Tensor) -> torch.Tensor:
    gauge_bias = self.fc2.gauge_bias
    full_bias = torch.cat((gauge_bias, -gauge_bias.sum().reshape(1)), dim=0)
    if full_bias.requires_grad:
        full_bias.retain_grad()
    self._full_fc2_bias = full_bias
    y = F.linear(F.gelu(self.fc1(x)), self.fc2.weight, full_bias)
    return self.drop(y)

def forward(self, x: torch.Tensor) -> torch.Tensor:
    bias = F.pad(self.bias_gauge, (0, 1))
    self._full_bias_grad = None
    if torch.is_grad_enabled():
        bias.register_hook(self._capture_full_bias_grad)
    return F.linear(x, self.weight, bias)

def _capture_omitted_bias_grad(self, grad: torch.Tensor) -> torch.Tensor:
    self._omitted_proj_bias_grad = grad[..., -1].sum().detach()
    return grad

class AttentionWeightAnchoredLinear(nn.Module):
    """QKV projection with two zero anchors and seven query scale anchors."""

    def __init__(self, in_features: int, out_features: int):
        super().__init__()
        self.in_features = in_features
        self.out_features = out_features
        nn.Linear(in_features, out_features, bias=False)
        self.weight_rest = nn.Parameter(torch.empty(out_features * in_features - 9))

    def weight_tensor(self) -> torch.Tensor:
        zero = self.weight_rest.new_zeros(1)
        fixed = self.weight_rest.new_full((1,), 0.02)
        return torch.cat((zero, self.weight_rest[:1], zero, self.weight_rest[1:2], fixed, self.weight_rest[2:5], fixed, self.weight_rest[5:12], fixed, self.weight_rest[12:27], fixed, self.weight_rest[27:34], fixed, self.weight_rest[34:41], fixed, self.weight_rest[41:48], fixed, self.weight_rest[48:])).view(self.out_features, self.in_features)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return F.linear(x, self.weight_tensor())

